import { useMemo, useRef, useState } from 'react';
import type { CalendarDefinition, ProjectData } from '../domain/types';
import { newId } from '../domain/model';
import { calendarDateToTick, formatCalendarTick, validateCalendar } from '../domain/time';
import { calendarDisplayUnits } from '../domain/timeEditing';
import { Modal } from './components';
import { type TimelineSave } from './TimelineEditors';

type RepeatingCalendar = Extract<CalendarDefinition, { kind: 'repeating' }>;
export function WorldCalendars({ project, onSave }: { project: ProjectData; onSave: TimelineSave }) {
  const [editing, setEditing] = useState<CalendarDefinition | null>(null), [error, setError] = useState('');
  return <><p>暦は世界内tickを年月日で表す規則です。暦と本編開始を選び直しても、出来事のtickは移動しません。</p><div className="world-list">{project.calendars.map(calendar => <article key={calendar.id}><h4>{calendar.name}</h4><p>{calendar.kind === 'gregorian' ? '先発グレゴリオ暦' : `${calendar.years.length}年の繰返し周期`} · 1日 {calendar.ticksPerDay} tick · 原点 {calendar.originLabel}</p><p>{calendarDisplayUnits(calendar).filter(unit => !unit.available).map(unit => `${unit.label}：${unit.reason}`).join('、')}</p><div className="world-inline-actions"><button type="button" className="button secondary" onClick={() => setEditing(calendar)}>暦の規則を編集</button><button type="button" className="button subtle" disabled={project.calendarId === calendar.id} onClick={async () => { try { await onSave({ ...project, calendarId: calendar.id }, '作品の表示暦を選択'); setError(''); } catch (cause) { setError((cause as Error).message); } }}>{project.calendarId === calendar.id ? '作品の表示暦' : '作品の表示暦にする'}</button></div></article>)}</div>{error && <p className="error-notice" role="alert">{error}</p>}<button type="button" className="button primary" onClick={() => setEditing({ id: `calendar-${newId()}`, name: '', kind: 'repeating', originLabel: '0年1月1日', ticksPerDay: '1', years: [{ months: [{ name: '第1月', days: 30 }] }] })}>独自暦を追加</button><p className="field-hint">繰返し暦は最大400年、1年24月、各月400日までの周期で定義します。周期で表せない規則は登録できません。対応がない暦同士の日時は、自動で換算しません。</p>{editing && <CalendarForm key={editing.id} calendar={editing} project={project} onSave={onSave} onClose={() => setEditing(null)}/>}</>;
}
function CalendarForm({ calendar, project, onSave, onClose }: { calendar: CalendarDefinition; project: ProjectData; onSave: TimelineSave; onClose: () => void }) {
  const [draft, setDraft] = useState(() => structuredClone(calendar)), [yearPage, setYearPage] = useState(0), [preview, setPreview] = useState<CalendarDefinition | null>(null), [date, setDate] = useState({ year: '0', month: '1', day: '1', tickOfDay: '0' }), [error, setError] = useState(''), [busy, setBusy] = useState(false);
  const [previewBase, setPreviewBase] = useState<ProjectData | null>(null);
  const saving = useRef(false);
  const stale = !!previewBase && (previewBase.projectId !== project.projectId || previewBase.revision !== project.revision);
  const original = project.calendars.find(item => item.id === calendar.id), validation = useMemo(() => validateCalendar(draft), [draft]);
  const update = (value: Partial<CalendarDefinition>) => { setDraft(previous => ({ ...previous, ...value } as CalendarDefinition)); setPreview(null); };
  const updateYears = (years: RepeatingCalendar['years']) => { if (draft.kind === 'repeating') update({ years }); };
  const changedIds = useMemo(() => (previewBase ?? project).entities.filter(entity => { if (entity.deletedAt) return false; if (entity.kind === 'event') return 'calendarId' in entity.data.time && entity.data.time.calendarId === draft.id; if (entity.kind === 'character') return [entity.data.birth, entity.data.death].some(time => time && 'calendarId' in time && time.calendarId === draft.id); return false; }).map(entity => entity.id), [previewBase, project.entities, draft.id]);
  let converted = '', conversionError = ''; if (validation.ok) try { if (!/^-?(?:0|[1-9][0-9]*)$/.test(date.year) || !/^[1-9][0-9]*$/.test(date.month) || !/^[1-9][0-9]*$/.test(date.day)) throw new Error('年月日を整数で入力してください。'); const tick = calendarDateToTick({ year: date.year, month: Number(date.month), day: Number(date.day), tickOfDay: date.tickOfDay }, draft); converted = `${tick} tick · ${formatCalendarTick(tick, draft)}`; } catch (cause) { conversionError = (cause as Error).message; }
  const yearStart = yearPage * 10;
  return <Modal title="暦を通常入力で定義" wide onClose={() => { if (!busy) onClose(); }}><fieldset disabled={busy} className="world-save-fields"><label>暦の名称<input aria-label="暦の名称" value={draft.name} onChange={event => update({ name: event.target.value })}/></label><label>暦の種類<select aria-label="暦の種類" value={draft.kind} onChange={event => { setPreview(null); setYearPage(0); setDraft(event.target.value === 'gregorian' ? { id: draft.id, name: draft.name, originLabel: draft.originLabel, ticksPerDay: '86400', kind: 'gregorian' } : { id: draft.id, name: draft.name, originLabel: draft.originLabel, ticksPerDay: draft.ticksPerDay, kind: 'repeating', years: [{ months: [{ name: '第1月', days: 30 }] }] }); }}><option value="repeating">独自の繰返し暦</option><option value="gregorian">先発グレゴリオ暦</option></select></label><label>原点の呼び方<input aria-label="暦の原点ラベル" value={draft.originLabel} onChange={event => update({ originLabel: event.target.value })}/></label><label>1日のtick数<input aria-label="1日のtick数" inputMode="numeric" disabled={draft.kind === 'gregorian'} value={draft.ticksPerDay} onChange={event => update({ ticksPerDay: event.target.value })}/></label>{draft.kind === 'repeating' && <><p>周期の第1年は0年です。最後の年の次に第1年の規則へ戻ります。閏年は周期内の別の年として追加できます。</p><div className="world-calendar-years">{draft.years.slice(yearStart, yearStart + 10).map((year, offset) => { const y = yearStart + offset; const replace = (months: RepeatingCalendar['years'][number]['months']) => updateYears(draft.years.map((item, i) => i === y ? { months } : item)); return <section key={y} className="world-calendar-year"><h3>周期の第{y + 1}年</h3>{year.months.map((month, m) => <div key={m} className="world-calendar-month"><label>第{m + 1}月の名称<input aria-label={`周期${y + 1}年の${m + 1}月名`} value={month.name} onChange={event => replace(year.months.map((item, i) => i === m ? { ...item, name: event.target.value } : item))}/></label><label>日数<input aria-label={`周期${y + 1}年の${m + 1}月の日数`} type="number" min="1" max="400" step="1" value={Number.isNaN(month.days) ? '' : month.days} onChange={event => replace(year.months.map((item, i) => i === m ? { ...item, days: event.target.value === '' ? NaN : Number(event.target.value) } : item))}/></label><button type="button" className="button subtle small" aria-label={`${m + 1}月を前へ`} disabled={m === 0} onClick={() => { const months = [...year.months]; [months[m - 1], months[m]] = [months[m], months[m - 1]]; replace(months); }}>↑</button><button type="button" className="button subtle small" aria-label={`${m + 1}月を後へ`} disabled={m === year.months.length - 1} onClick={() => { const months = [...year.months]; [months[m + 1], months[m]] = [months[m], months[m + 1]]; replace(months); }}>↓</button><button type="button" className="button danger small" disabled={year.months.length <= 1} onClick={() => replace(year.months.filter((_, i) => i !== m))}>月を除く</button></div>)}<div className="world-inline-actions"><button type="button" className="button secondary small" disabled={year.months.length >= 24} onClick={() => replace([...year.months, { name: `第${year.months.length + 1}月`, days: 30 }])}>月を追加</button><button type="button" className="button secondary small" disabled={y === 0} onClick={() => { const years = [...draft.years]; [years[y - 1], years[y]] = [years[y], years[y - 1]]; updateYears(years); }}>年を前へ</button><button type="button" className="button secondary small" disabled={y === draft.years.length - 1} onClick={() => { const years = [...draft.years]; [years[y + 1], years[y]] = [years[y], years[y + 1]]; updateYears(years); }}>年を後へ</button><button type="button" className="button danger small" disabled={draft.years.length <= 1} onClick={() => { updateYears(draft.years.filter((_, i) => i !== y)); setYearPage(Math.min(yearPage, Math.max(0, Math.ceil((draft.years.length - 1) / 10) - 1))); }}>この年を除く</button></div></section>; })}</div><div className="world-inline-actions"><button type="button" className="button secondary" disabled={yearPage === 0} onClick={() => setYearPage(yearPage - 1)}>前の10年</button><span>{yearPage + 1} / {Math.ceil(draft.years.length / 10)} · {draft.years.length}年周期</span><button type="button" className="button secondary" disabled={yearStart + 10 >= draft.years.length} onClick={() => setYearPage(yearPage + 1)}>次の10年</button><button type="button" className="button secondary" disabled={draft.years.length >= 400} onClick={() => updateYears([...draft.years, structuredClone(draft.years[draft.years.length - 1])])}>周期に年を追加</button></div></>}
    <h3>年月日の確認</h3><div className="world-filters">{(['year', 'month', 'day', 'tickOfDay'] as const).map(key => <label key={key}>{{ year: '年', month: '月', day: '日', tickOfDay: '日内tick' }[key]}<input aria-label={`暦の確認${key}`} value={date[key]} onChange={event => setDate({ ...date, [key]: event.target.value })}/></label>)}</div>{converted && <p role="status">{converted}</p>}{conversionError && <p className="field-error" role="alert">{conversionError}</p>}{!validation.ok && <div className="field-error" role="alert">{validation.issues.map(issue => <p key={issue.path}>{issue.message}</p>)}</div>}
    <button type="button" className="button secondary" disabled={!validation.ok} onClick={() => { if (validation.ok && !saving.current) { setPreview(structuredClone(draft)); setPreviewBase(structuredClone(project)); setError(''); } }}>規則変更の影響を確認</button>{preview && <div className="timeline-time-preview"><h3>{original ? '暦の規則を変更' : '新しい暦を追加'}</h3><p>{changedIds.length}件の出来事・人物の年月日表示と年齢計算が変わる可能性があります。世界内tick、本編開始、日時制約の整数値は保持します。</p><p>この暦を使う公開済みの作品版は保存済みの規則を保持します。</p></div>}{stale && <p className="info-notice" role="status">影響確認後に作品が更新されました。入力を保持しています。規則変更の影響を再確認してください。</p>}{error && <p className="error-notice" role="alert">{error}</p>}<div className="modal-actions"><button type="button" className="button secondary" disabled={busy} onClick={onClose}>中止</button><button type="button" className="button primary" disabled={busy || stale || !preview || !previewBase || !validation.ok} onClick={async () => { if (saving.current || stale || !preview || !previewBase) return; saving.current = true; setBusy(true); try { await onSave({ ...previewBase, calendars: original ? previewBase.calendars.map(item => item.id === preview.id ? preview : item) : [...previewBase.calendars, preview] }, '確認した暦の規則を保存'); onClose(); } catch (cause) { setError((cause as Error).message); } finally { saving.current = false; setBusy(false); } }}>確認した暦を保存</button></div></fieldset></Modal>;
}
